/**
 * Swift 持有的 core 对象。线程安全，所有方法可从任意线程调用。
 */
public protocol KansoCoreProtocol: AnyObject, Sendable {
    
    /**
     * 用 License Key 激活（仅 Direct 渠道）。
     */
    func activateLicense(key: String) async throws  -> FfiEntitlement
    
    /**
     * 取消该会话正在进行的终端内传输。
     */
    func cancelTerminalTransfer(sessionId: UInt64) 
    
    /**
     * 取消传输；未知或已结束的传输忽略。
     */
    func cancelTransfer(transfer: UInt64) 
    
    /**
     * 清空缓冲区（⌘K）。
     */
    func clearBuffer(sessionId: UInt64) throws 
    
    /**
     * 清除命令历史。
     */
    func clearHistory() throws 
    
    /**
     * 清除选区。
     */
    func clearSelection(sessionId: UInt64) throws 
    
    /**
     * 用户主动关闭会话；会话不存在时忽略。
     */
    func closeSession(sessionId: UInt64) 
    
    /**
     * 提取命令块文本；块已裁掉或会话不存在时为 `None`。
     */
    func commandBlockText(sessionId: UInt64, id: UInt64, part: FfiBlockText)  -> String?
    
    /**
     * 对最新输入同步生成候选，不等外部 IO。
     */
    func complete(sessionId: UInt64, input: String, sources: FfiCompletionSources)  -> FfiCompletionSuggestions
    
    /**
     * 只探测外部来源，不生成候选。
     */
    func completionPlan(sessionId: UInt64, input: String, sources: FfiCompletionSources)  -> FfiCompletionSuggestions
    
    /**
     * 获取仍可编辑的命令输入。
     */
    func completionState(sessionId: UInt64)  -> FfiCompletionState?
    
    /**
     * 删除分组及其内容；调用方应先用 `group_delete_impact` 让用户确认。
     */
    func deleteGroup(id: String) async throws 
    
    /**
     * 删除 Profile，连带删除它的凭据。
     */
    func deleteProfile(id: String) async throws 
    
    /**
     * 删除一条 Sender 命令；不存在时视为成功。
     */
    func deleteSnippet(id: String) throws 
    
    /**
     * 下载远端文件或目录到本地目录；立即返回传输 id，进度走事件。
     * `conflict` 为 `Fail` 且目标已存在时传输以 `Failed(already_exists = true)` 结束；
     * `Skip` 时已存在的文件被跳过，结果 `Completed(skipped)` 带回跳过数。
     */
    func download(sessionId: UInt64, remotePath: String, localDir: String, conflict: FfiConflictPolicy) throws  -> UInt64
    
    /**
     * 当前授权状态；未授权返回 `nil`。
     */
    func entitlement()  -> FfiEntitlement?
    
    /**
     * 导出全部会话、分组、Sender 命令到 `.kanso` 文件（不含凭据）。
     */
    func exportData(path: String) async throws 
    
    /**
     * 终端获得 / 失去焦点。
     */
    func focus(sessionId: UInt64, focused: Bool) throws 
    
    /**
     * 删除分组会连带删除多少内容。
     */
    func groupDeleteImpact(id: String) throws  -> FfiDeleteImpact
    
    /**
     * 全部分组。
     */
    func groups()  -> [FfiGroup]
    
    /**
     * 当前是否有选区。
     */
    func hasSelection(sessionId: UInt64)  -> Bool
    
    /**
     * 由帧里的超链接 id（OSC 8）取 URL；id 无效或会话不存在为 `None`。
     */
    func hyperlinkUrl(sessionId: UInt64, id: UInt32)  -> String?
    
    /**
     * 从 `.kanso` 文件导入。
     */
    func importData(path: String) async throws  -> FfiImportReport
    
    /**
     * 导入所选别名到分组 `group`（`None` 为顶层）。`path` 与扫描时一致，`nil` 为默认的 `~/.ssh/config`。
     */
    func importSshConfig(path: String?, aliases: [String], group: String?) async throws  -> FfiSshConfigImportReport
    
    /**
     * 将相邻块的提示符滚动到视口顶部附近。
     */
    func jumpCommandBlock(sessionId: UInt64, forward: Bool) throws  -> UInt64?
    
    /**
     * 一次按键；core 负责编码成终端字节序列。IME 组字期间的按键不要发。
     */
    func key(sessionId: UInt64, event: FfiKeyEvent) throws 
    
    /**
     * 读取本地 Shell 默认配置。
     */
    func localShellDefaults()  -> FfiLocalProfile
    
    /**
     * 鼠标事件。
     */
    func mouse(sessionId: UInt64, event: FfiMouseEvent) throws 
    
    /**
     * 打开会话，立即返回会话 id；连接进度通过事件推送。
     */
    func openSession(target: FfiOpenTarget, size: FfiGridSize) throws  -> UInt64
    
    /**
     * 粘贴。
     */
    func paste(sessionId: UInt64, content: FfiPasteContent) throws 
    
    /**
     * 全部 Profile。
     */
    func profiles()  -> [FfiProfile]
    
    /**
     * 发起商店购买（MAS）。
     */
    func purchase() async throws  -> FfiPurchaseOutcome
    
    /**
