/**
 * Sender 的即时进度。
 */
public struct FfiSenderStatus: Equatable, Hashable {
    /**
     * 手动批次是否运行。
     */
    public var manualRunning: Bool
    /**
     * 重复任务是否运行。
     */
    public var repeatRunning: Bool
    /**
     * 已完成轮次。
     */
    public var rounds: UInt32
    /**
     * 计划轮次。
     */
    public var count: UInt32
    /**
     * 下一轮倒计时毫秒数。
     */
    public var nextInMs: UInt64
    /**
     * 本轮已发送行数。
     */
    public var sent: UInt32
    /**
     * 本轮计划行数。
     */
    public var total: UInt32
    /**
     * 状态栏提示。
     */
    public var notices: [FfiMessage]
    /**
     * 本次更新包含发送失败或跳过的对象。
     */
    public var hasFailures: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * 手动批次是否运行。
         */manualRunning: Bool, 
        /**
         * 重复任务是否运行。
         */repeatRunning: Bool, 
        /**
         * 已完成轮次。
         */rounds: UInt32, 
        /**
         * 计划轮次。
         */count: UInt32, 
        /**
         * 下一轮倒计时毫秒数。
         */nextInMs: UInt64, 
        /**
         * 本轮已发送行数。
         */sent: UInt32, 
        /**
         * 本轮计划行数。
         */total: UInt32, 
        /**
         * 状态栏提示。
         */notices: [FfiMessage], 
        /**
         * 本次更新包含发送失败或跳过的对象。
         */hasFailures: Bool) {
        self.manualRunning = manualRunning
        self.repeatRunning = repeatRunning
        self.rounds = rounds
        self.count = count
        self.nextInMs = nextInMs
        self.sent = sent
        self.total = total
        self.notices = notices
        self.hasFailures = hasFailures
    }

    

    
}

