/**
 * 会话活动状态。
 */

public enum FfiActivity: Equatable, Hashable {
    
    /**
     * 空闲。
     */
    case idle
    /**
     * 有命令在运行。
     */
    case commandRunning
    /**
     * agent 在等待输入。
     */
    case agentIdle(
        /**
         * agent 种类。
         */agent: FfiAgentKind
    )
    /**
     * agent 在工作。
     */
    case agentWorking(
        /**
         * agent 种类。
         */agent: FfiAgentKind
    )





}

#if compiler(>=6)
extension FfiActivity: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiActivity: FfiConverterRustBuffer {
    typealias SwiftType = FfiActivity

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiActivity {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .idle
        
        case 2: return .commandRunning
        
        case 3: return .agentIdle(agent: try FfiConverterTypeFfiAgentKind.read(from: &buf)
        )
        
        case 4: return .agentWorking(agent: try FfiConverterTypeFfiAgentKind.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiActivity, into buf: inout [UInt8]) {
        switch value {
        
        
        case .idle:
            writeInt(&buf, Int32(1))
        
        
        case .commandRunning:
            writeInt(&buf, Int32(2))
        
        
        case let .agentIdle(agent):
            writeInt(&buf, Int32(3))
            FfiConverterTypeFfiAgentKind.write(agent, into: &buf)
            
        
        case let .agentWorking(agent):
            writeInt(&buf, Int32(4))
            FfiConverterTypeFfiAgentKind.write(agent, into: &buf)
            
        }
    }
}


