     * 字节数，由平台格式化器显示成 `1.2 MB`。
     */
    case byteSize(
        /**
         * 字节数。
         */bytes: UInt64
    )
    /**
     * 字符串列表，由平台的列表格式化器连接。
     */
    case strList(
        /**
         * 列表项。
         */values: [String]
    )
    /**
     * 选择器取值（Fluent select 的分支 key）。
     */
    case select(
        /**
         * 分支 key。
         */key: String
    )
    /**
     * 失败原因：先用 `key`（`reason-*`）本地化，`detail` 仅 `reason-other` 有，为英文技术细节。
     */
    case reason(
        /**
         * 本地化子 key。
         */key: String, 
        /**
         * 英文技术细节，不本地化。
         */detail: String?
    )
    /**
     * 连接对象，用 `endpoint-direct` / `endpoint-via` 子 key 渲染。
     */
    case endpoint(
        /**
         * 主机名或地址。
         */host: String, 
        /**
         * 端口。
         */port: UInt16, 
        /**
         * 经过的跳板机显示名；空表示直连。
