        switch variant {
        
        case 1: return .str(value: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .int(value: try FfiConverterInt64.read(from: &buf)
        )
        
        case 3: return .byteSize(bytes: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .strList(values: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 5: return .select(key: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .reason(key: try FfiConverterString.read(from: &buf), detail: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 7: return .endpoint(host: try FfiConverterString.read(from: &buf), port: try FfiConverterUInt16.read(from: &buf), via: try FfiConverterSequenceString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiArgValue, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .str(value):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(value, into: &buf)
            
        
        case let .int(value):
            writeInt(&buf, Int32(2))
            FfiConverterInt64.write(value, into: &buf)
            
        
        case let .byteSize(bytes):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(bytes, into: &buf)
            
        
        case let .strList(values):
