        case let .reason(key,detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(key, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            
        
        case let .endpoint(host,port,via):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(host, into: &buf)
            FfiConverterUInt16.write(port, into: &buf)
            FfiConverterSequenceString.write(via, into: &buf)
            
