/**
 * core 返回的错误（镜像 `kanso_core::CoreError`）。
 *
 * Swift 侧表现为 `Error`，`async throws` / `throws` 方法抛出它。
 * 只有 `User` 带可展示给用户的消息；其余情况 UI 显示通用失败提示，`detail` 只进日志。
 * 注意：`NoSuch*` 变体不携带 id（调用方自己知道刚才传了哪个 id）。
 */
public 
enum FfiCoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * 可直接展示给用户的错误；用 `message.key` 查本地化目录。
     */
    case User(
        /**
         * 本地化用的消息。
         */message: FfiMessage
    )
    /**
     * 会话不存在（已关闭或 id 无效）。
     */
    case NoSuchSession
    /**
     * Profile 不存在。
     */
    case NoSuchProfile
    /**
     * 分组不存在。
     */
    case NoSuchGroup
    /**
     * 该会话不支持此操作。
     */
    case NotSupported
    /**
     * 内部错误；`detail` 为英文技术细节，只进日志，不展示给用户。
     */
    case Internal(
        /**
         * 技术细节。
         */detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

