    typealias SwiftType = FfiCoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiCoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .User(
            message: try FfiConverterTypeFfiMessage.read(from: &buf)
            )
        case 2: return .NoSuchSession
        case 3: return .NoSuchProfile
        case 4: return .NoSuchGroup
        case 5: return .NotSupported
        case 6: return .Internal(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiCoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .User(message):
            writeInt(&buf, Int32(1))
            FfiConverterTypeFfiMessage.write(message, into: &buf)
            
        
        case .NoSuchSession:
            writeInt(&buf, Int32(2))
        
        
        case .NoSuchProfile:
            writeInt(&buf, Int32(3))
        
        
        case .NoSuchGroup:
            writeInt(&buf, Int32(4))
        
        
        case .NotSupported:
            writeInt(&buf, Int32(5))
        
        
        case let .Internal(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


