/**
 * core 推送给 UI 的事件。运行时 id（会话、传输、提问）都是 `u64`。
 */

public enum FfiCoreEvent: Equatable, Hashable {
    
    /**
     * 会话状态变化。
     */
    case sessionStateChanged(
        /**
         * 会话。
         */session: UInt64, 
        /**
         * 新状态。
         */state: FfiSessionState
    )
    /**
     * 终端由干净变脏：UI 应在渲染线程取帧。
     */
    case terminalDirty(
        /**
         * 会话。
         */session: UInt64
    )
    /**
     * 工作目录、主机或 git 分支变化。
     */
    case locationChanged(
        /**
         * 会话。
         */session: UInt64, 
        /**
         * 当前工作目录。
         */cwd: String?, 
        /**
         * 工作目录所在主机。
         */cwdHost: String?, 
        /**
         * git 分支。
         */gitBranch: String?
    )
    /**
     * 会话活动状态变化。
     */
    case activityChanged(
        /**
         * 会话。
         */session: UInt64, 
        /**
         * 新活动状态。
         */activity: FfiActivity
    )
    /**
     * 连接用到了过时算法，需要提示用户。
     */
    case legacyAlgorithms(
        /**
         * 会话。
         */session: UInt64, 
        /**
         * 各跳使用的过时算法。
         */hops: [FfiLegacyHop]
    )
    /**
     * 需要提示用户的通知。
     */
    case notice(
        /**
         * 关联会话；全局通知为 `None`。
         */session: UInt64?, 
        /**
         * 级别。
         */level: FfiNoticeLevel, 
        /**
         * 可展示给用户的消息。
         */message: FfiMessage
    )
    /**
     * 需要用户回答的请求；用 `respond_prompt` 应答。
     */
    case prompt(
        /**
         * 提问 id。
         */prompt: UInt64, 
        /**
         * 关联会话。
         */session: UInt64?, 
        /**
         * 请求内容。
         */request: FfiPromptRequest
    )
    /**
     * 提问已失效（会话关闭等），UI 应关闭对应对话框。
     */
    case promptDismissed(
        /**
         * 提问 id。
         */prompt: UInt64
    )
    /**
     * 传输开始。
     */
    case transferStarted(
        /**
         * 传输 id。
         */transfer: UInt64, 
        /**
         * 会话。
         */session: UInt64, 
        /**
         * 协议。
         */`protocol`: FfiXferProtocol, 
        /**
         * 方向。
         */direction: FfiTransferDirection, 
        /**
         * 文件名或目录名。
         */name: String, 
        /**
         * 总字节数；未知为 `None`。
         */totalBytes: UInt64?
    )
    /**
     * 传输进度。
     */
    case transferProgress(
        /**
         * 传输 id。
         */transfer: UInt64, 
        /**
         * 已完成字节数。
         */doneBytes: UInt64, 
        /**
         * 总字节数；未知为 `None`。
         */totalBytes: UInt64?
    )
    /**
     * 传输结束。
     */
    case transferFinished(
        /**
         * 传输 id。
         */transfer: UInt64, 
        /**
         * 结果。
         */outcome: FfiTransferOutcome
    )





}

