    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiCoreEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .sessionStateChanged(session: try FfiConverterUInt64.read(from: &buf), state: try FfiConverterTypeFfiSessionState.read(from: &buf)
        )
        
        case 2: return .terminalDirty(session: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 3: return .locationChanged(session: try FfiConverterUInt64.read(from: &buf), cwd: try FfiConverterOptionString.read(from: &buf), cwdHost: try FfiConverterOptionString.read(from: &buf), gitBranch: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .activityChanged(session: try FfiConverterUInt64.read(from: &buf), activity: try FfiConverterTypeFfiActivity.read(from: &buf)
        )
        
        case 5: return .legacyAlgorithms(session: try FfiConverterUInt64.read(from: &buf), hops: try FfiConverterSequenceTypeFfiLegacyHop.read(from: &buf)
        )
        
        case 6: return .notice(session: try FfiConverterOptionUInt64.read(from: &buf), level: try FfiConverterTypeFfiNoticeLevel.read(from: &buf), message: try FfiConverterTypeFfiMessage.read(from: &buf)
        )
        
        case 7: return .prompt(prompt: try FfiConverterUInt64.read(from: &buf), session: try FfiConverterOptionUInt64.read(from: &buf), request: try FfiConverterTypeFfiPromptRequest.read(from: &buf)
        )
        
        case 8: return .promptDismissed(prompt: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 9: return .transferStarted(transfer: try FfiConverterUInt64.read(from: &buf), session: try FfiConverterUInt64.read(from: &buf), protocol: try FfiConverterTypeFfiXferProtocol.read(from: &buf), direction: try FfiConverterTypeFfiTransferDirection.read(from: &buf), name: try FfiConverterString.read(from: &buf), totalBytes: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        case 10: return .transferProgress(transfer: try FfiConverterUInt64.read(from: &buf), doneBytes: try FfiConverterUInt64.read(from: &buf), totalBytes: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        case 11: return .transferFinished(transfer: try FfiConverterUInt64.read(from: &buf), outcome: try FfiConverterTypeFfiTransferOutcome.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiCoreEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .sessionStateChanged(session,state):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(session, into: &buf)
            FfiConverterTypeFfiSessionState.write(state, into: &buf)
            
        
        case let .terminalDirty(session):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(session, into: &buf)
            
        
        case let .locationChanged(session,cwd,cwdHost,gitBranch):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(session, into: &buf)
            FfiConverterOptionString.write(cwd, into: &buf)
            FfiConverterOptionString.write(cwdHost, into: &buf)
            FfiConverterOptionString.write(gitBranch, into: &buf)
            
        
        case let .activityChanged(session,activity):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(session, into: &buf)
            FfiConverterTypeFfiActivity.write(activity, into: &buf)
            
        
        case let .legacyAlgorithms(session,hops):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(session, into: &buf)
            FfiConverterSequenceTypeFfiLegacyHop.write(hops, into: &buf)
            
        
        case let .notice(session,level,message):
            writeInt(&buf, Int32(6))
            FfiConverterOptionUInt64.write(session, into: &buf)
            FfiConverterTypeFfiNoticeLevel.write(level, into: &buf)
            FfiConverterTypeFfiMessage.write(message, into: &buf)
            
        
        case let .prompt(prompt,session,request):
            writeInt(&buf, Int32(7))
            FfiConverterUInt64.write(prompt, into: &buf)
            FfiConverterOptionUInt64.write(session, into: &buf)
            FfiConverterTypeFfiPromptRequest.write(request, into: &buf)
            
        
        case let .promptDismissed(prompt):
            writeInt(&buf, Int32(8))
            FfiConverterUInt64.write(prompt, into: &buf)
            
        
        case let .transferStarted(transfer,session,`protocol`,direction,name,totalBytes):
            writeInt(&buf, Int32(9))
            FfiConverterUInt64.write(transfer, into: &buf)
            FfiConverterUInt64.write(session, into: &buf)
            FfiConverterTypeFfiXferProtocol.write(`protocol`, into: &buf)
            FfiConverterTypeFfiTransferDirection.write(direction, into: &buf)
            FfiConverterString.write(name, into: &buf)
            FfiConverterOptionUInt64.write(totalBytes, into: &buf)
            
        
        case let .transferProgress(transfer,doneBytes,totalBytes):
            writeInt(&buf, Int32(10))
            FfiConverterUInt64.write(transfer, into: &buf)
            FfiConverterUInt64.write(doneBytes, into: &buf)
            FfiConverterOptionUInt64.write(totalBytes, into: &buf)
            
        
        case let .transferFinished(transfer,outcome):
            writeInt(&buf, Int32(11))
            FfiConverterUInt64.write(transfer, into: &buf)
            FfiConverterTypeFfiTransferOutcome.write(outcome, into: &buf)
            
        }
    }
}


