    typealias SwiftType = FfiPromptRequest

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiPromptRequest {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .hostKeyChanged(endpoint: try FfiConverterTypeFfiEndpoint.read(from: &buf), keyType: try FfiConverterString.read(from: &buf), fingerprintSha256: try FfiConverterString.read(from: &buf), knownHostsPath: try FfiConverterString.read(from: &buf), line: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 2: return .keyboardInteractive(endpoint: try FfiConverterTypeFfiEndpoint.read(from: &buf), user: try FfiConverterString.read(from: &buf), name: try FfiConverterString.read(from: &buf), instruction: try FfiConverterString.read(from: &buf), preamble: try FfiConverterSequenceString.read(from: &buf), questions: try FfiConverterSequenceTypeFfiKbdQuestion.read(from: &buf)
        )
        
        case 3: return .credential(endpoint: try FfiConverterTypeFfiEndpoint.read(from: &buf), user: try FfiConverterString.read(from: &buf), kind: try FfiConverterTypeFfiCredentialKind.read(from: &buf)
        )
        
        case 4: return .zmodemSaveFile(suggestedName: try FfiConverterString.read(from: &buf), size: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        case 5: return .zmodemPickFiles
        
        case 6: return .xmodemPickFile
        
        case 7: return .xmodemSaveFile
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiPromptRequest, into buf: inout [UInt8]) {
        switch value {
        
        
