            writeInt(&buf, Int32(1))
            FfiConverterTypeFfiEndpoint.write(endpoint, into: &buf)
            FfiConverterString.write(keyType, into: &buf)
            FfiConverterString.write(fingerprintSha256, into: &buf)
            FfiConverterString.write(knownHostsPath, into: &buf)
