        switch value {
        
        
        case let .completed(skipped):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(skipped, into: &buf)
            
        
        case .cancelled:
            writeInt(&buf, Int32(2))
        
        
        case let .failed(message,alreadyExists):
            writeInt(&buf, Int32(3))
            FfiConverterTypeFfiMessage.write(message, into: &buf)
            FfiConverterBool.write(alreadyExists, into: &buf)
            
        }
    }
}


